__dexpand_loaders["src.growth_rates"] = function()
  -- The two experience curves Gen 1 does not ship.
  --
  -- Gen 1 has MEDIUM_FAST, SLIGHTLY_FAST, SLIGHTLY_SLOW, MEDIUM_SLOW and FAST.
  -- Gen 2+ species also use ERRATIC and FLUCTUATING, which is exactly why
  -- Sanqui's pokered fork had to add them; here they are ordinary registry
  -- records.  R.growth_rates takes `expForLevel = f.fn` and validates that the
  -- curve increases, so these are plain functions of level.
  local GrowthRates = {}

  local function erratic(n)
    if n < 50 then return math.floor(n^3 * (100 - n) / 50) end
    if n < 68 then return math.floor(n^3 * (150 - n) / 100) end
    if n < 98 then return math.floor(n^3 * math.floor((1911 - 10 * n) / 3) / 500) end
    return math.floor(n^3 * (160 - n) / 100)
  end

  local function fluctuating(n)
    if n < 15 then
      return math.floor(n^3 * (math.floor((n + 1) / 3) + 24) / 50)
    end
    if n < 36 then return math.floor(n^3 * (n + 14) / 50) end
    return math.floor(n^3 * (math.floor(n / 2) + 32) / 50)
  end

  GrowthRates.CURVES = {
    ERRATIC = erratic,
    FLUCTUATING = fluctuating,
  }

  return GrowthRates
end

__dexpand_loaders["src.moves"] = function()
  -- Types and moves for dex_expansion.
  --
  -- EXISTENCE IS UNCONDITIONAL.  AVAILABILITY IS OPTIONAL.  The same rule the
  -- species layer uses, applied here for the same reason: a saved mon stores
  -- the moves it knows, so a move that stops being registered between two
  -- boots would be scrubbed off that mon.  Both modes therefore register
  -- every type and every move.  Only what the LEARNSETS point at changes.
  --
  -- MODERN  species keep their real typing (STEEL / DARK / FAIRY included) and
  --         learn the real Gen 2-5 level-up moves.
  -- RETRO   species are retyped onto the original 15 (DARK->GHOST,
  --         STEEL->GROUND, FAIRY->NORMAL) and every modern move resolves to
  --         its nearest Gen 1 ancestor via data/retro.lua.  A modern status
  --         move with no ancestor is REMOVED from the learnset rather than
  --         faked into a damaging move.
  --
  -- Verified against the engine:
  --   * src/mods/Schemas.lua R.type_chart takes types and matchups on ONE
  --     registry, told apart by whether the id contains ">":
  --         type    -> { name = ..., category = "physical"|"special" }
  --         matchup -> { multiplier = n }   -- n is x10 fixed point
  --   * src/battle/TypeChart.lua: "Gen 1 splits physical from special by TYPE,
  --     not by move", and reads the per-type `category` from the merged
  --     record.  So a new type carries its own damage class and works in the
  --     Gen 1 damage model without the per-move split as a prerequisite.
  --   * gen1recomp-modern-kanto registers NO types and NO moves -- it only
  --     patches matchup multipliers and per-move `category`.  Nothing here
  --     duplicates it; where both write the same matchup row the intent is
  --     identical, so last-write-wins is harmless.

  local NewMoves = __dexpand_require("data.moves")
  local Retro = __dexpand_require("data.retro")

  local Moves = {}

  -- Gen 2's type split, which is what a Gen 1 engine can express.
  local NEW_TYPES = {
    { id = "STEEL", name = "STEEL", category = "physical" },
    { id = "DARK", name = "DARK", category = "special" },
    { id = "FAIRY", name = "FAIRY", category = "special" },
  }

  Moves.RETRO_TYPE = { DARK = "GHOST", STEEL = "GROUND", FAIRY = "NORMAL" }

  -- Matchups for the three new types, x10 fixed point (5 = 0.5x, 20 = 2x,
  -- 0 = immune).  Only rows that differ from 1x are listed; the engine treats
  -- a missing row as neutral.  Attacking rows first, then how the new types
  -- are hit by the old ones.
  local MATCHUPS = {
    -- STEEL attacking
    { "STEEL>ICE", 20 }, { "STEEL>ROCK", 20 }, { "STEEL>FAIRY", 20 },
    { "STEEL>STEEL", 5 }, { "STEEL>FIRE", 5 }, { "STEEL>WATER", 5 },
    { "STEEL>ELECTRIC", 5 },
    -- DARK attacking
    { "DARK>PSYCHIC_TYPE", 20 }, { "DARK>GHOST", 20 },
    { "DARK>DARK", 5 }, { "DARK>FIGHTING", 5 }, { "DARK>FAIRY", 5 },
    -- FAIRY attacking
    { "FAIRY>FIGHTING", 20 }, { "FAIRY>DRAGON", 20 }, { "FAIRY>DARK", 20 },
    { "FAIRY>FIRE", 5 }, { "FAIRY>POISON", 5 }, { "FAIRY>STEEL", 5 },
    -- old types attacking STEEL
    { "NORMAL>STEEL", 5 }, { "GRASS>STEEL", 5 }, { "ICE>STEEL", 5 },
    { "FLYING>STEEL", 5 }, { "PSYCHIC_TYPE>STEEL", 5 }, { "BUG>STEEL", 5 },
    { "ROCK>STEEL", 5 }, { "DRAGON>STEEL", 5 },
    { "FIRE>STEEL", 20 }, { "FIGHTING>STEEL", 20 }, { "GROUND>STEEL", 20 },
    { "POISON>STEEL", 0 },
    -- old types attacking DARK
    { "PSYCHIC_TYPE>DARK", 0 }, { "GHOST>DARK", 5 },
    { "FIGHTING>DARK", 20 }, { "BUG>DARK", 20 },
    -- old types attacking FAIRY
    { "DRAGON>FAIRY", 0 }, { "FIGHTING>FAIRY", 5 }, { "BUG>FAIRY", 5 },
    { "POISON>FAIRY", 20 },
  }

  -- Register the types, their matchups and every new move.  Always, in both
  -- modes.  `register` is used rather than `patch` because these ids do not
  -- exist in the vanilla dataset; if another mod got there first, fall back to
  -- patch so we extend rather than fight.
  local function registerAll(mod)
    local types, matchups, moves = 0, 0, 0

    for _, t in ipairs(NEW_TYPES) do
      local ok = pcall(function()
        mod.content.type_chart:register(t.id,
          { name = t.name, category = t.category })
      end)
      if not ok then
        pcall(function()
          mod.content.type_chart:patch(t.id, { category = t.category })
        end)
      else
        types = types + 1
      end
    end

    for _, row in ipairs(MATCHUPS) do
      local id, multiplier = row[1], row[2]
      local ok = pcall(function()
        mod.content.type_chart:register(id, { multiplier = multiplier })
      end)
      if not ok then
        ok = pcall(function()
          mod.content.type_chart:patch(id, { multiplier = multiplier })
        end)
      end
      if ok then matchups = matchups + 1 end
    end

    for id, record in pairs(NewMoves) do
      local ok, err = pcall(function()
        mod.content.moves:register(id, record)
      end)
      if ok then
        moves = moves + 1
      else
        mod.log:warn("move %s not registered: %s", id, tostring(err))
      end
    end

    mod.log:info("registered %d types, %d matchups, %d moves",
      types, matchups, moves)
  end

  -- Returns (resolveMove, resolveTypes) for the active mode.
  -- resolveMove(id) -> id | nil   (nil means "drop this learnset entry")
  -- resolveTypes(list) -> list
  function Moves.apply(mod, mode)
    registerAll(mod)

    if mode ~= "retro" then
      return function(id) return id end, function(list) return list end
    end

    mod.log:info("RETRO GEN 1: learnsets resolve to Gen 1 moves and species "
      .. "are retyped onto the original 15")

    local function resolveMove(id)
      if NewMoves[id] == nil then return id end  -- already a Gen 1 move
      return Retro[id]                            -- may be nil: drop it
    end

    local function resolveTypes(list)
      local out, seen = {}, {}
      for _, t in ipairs(list or {}) do
        local mapped = Moves.RETRO_TYPE[t] or t
        if not seen[mapped] then
          seen[mapped] = true
          out[#out + 1] = mapped
        end
      end
      if #out == 0 then out[1] = "NORMAL" end
      return out
    end

    return resolveMove, resolveTypes
  end

  -- Rewrite one species record through the resolvers.  Returns a shallow copy
  -- so the loaded dataset is never mutated -- a second boot in the other mode
  -- has to start from the same source rows.
  function Moves.rewrite(record, resolveMove, resolveTypes)
    local out = {}
    for k, v in pairs(record) do out[k] = v end

    out.types = resolveTypes(record.types)

    local lvl1, seen = {}, {}
    for _, id in ipairs(record.level1Moves or {}) do
      local r = resolveMove(id)
      if r and not seen[r] then
        seen[r] = true
        lvl1[#lvl1 + 1] = r
      end
    end
    -- level1Moves must stay non-empty: the randomizer's eligibility gate
    -- rejects a species whose array is empty, which would silently drop it
    -- from the pool entirely.
    if #lvl1 == 0 then lvl1[1] = "TACKLE" end
    out.level1Moves = lvl1

    local learn = {}
    for _, entry in ipairs(record.learnset or {}) do
      local r = resolveMove(entry.move)
      if r then learn[#learn + 1] = { level = entry.level, move = r } end
    end
    out.learnset = learn

    return out
  end

  return Moves
end

__dexpand_loaders["src.encounters"] = function()
  -- Wild placement for Dex Expansion.
  --
  -- Everything here is built on one verified fact about the merge engine:
  --
  --   `encounters` is a RECORD registry, not a `deep` one.  In
  --   gen1recomp/src/mods/Merge.lua, a bare list under record semantics is
  --   copied over the destination -- it REPLACES.  Lists "extend only through
  --   the __append/__prepend wrappers".
  --
  -- All_Pokemon_Catchable_151_Mod writes bare 10-slot lists across 33 maps
  -- (VIRIDIAN_FOREST, ROUTE_3..25, the Safari Zone quadrants, Seafoam,
  -- Victory Road, Cerulean Cave, Power Plant, Pokemon Mansion B1F).  If this
  -- mod also wrote bare lists, whichever loaded last would silently erase the
  -- other -- no warning, no diagnostic.
  --
  -- Load order is "priority ascending, ties by id" (src/mods/Loader.lua), and
  -- every mod in the ecosystem ships priority 100, so ids decide:
  --
  --   all_pokemon_catchable_151_mod  <  dex_expansion  <  modern_kanto
  --     <  pokemon_randomizer  <  quality_of_life
  --
  -- We therefore land AFTER the catchability mod, and appending is enough to
  -- coexist with it.  The manifest still pins priority explicitly rather than
  -- leaning on alphabetical luck.

  local Encounters = {}

  -- A deterministic string hash, reproducible across platforms and runs
  -- without depending on Lua's PRNG (which differs by build).
  --
  -- LOVE runs LuaJIT, i.e. Lua 5.1 SYNTAX.  The bitwise operators `~`, `&`,
  -- `|`, `<<`, `>>` and integer division `//` are Lua 5.3+ and are a SYNTAX
  -- error under LuaJIT -- the whole file fails to parse, not just this
  -- function.  (`luac` from Lua 5.4 accepts them happily, which is exactly how
  -- a bad build slips through; validate with `luajit -bl`.)  So this is a plain
  -- polynomial hash in pure arithmetic: no bit ops, same result everywhere.
  local MASK = 2147483648 -- 2^31, keeps products inside a double exactly
  local function hash32(str)
    local h = 5381
    for i = 1, #str do
      h = (h * 33 + str:byte(i)) % MASK
    end
    return h
  end

  -- A deterministic 151-species subset, drawn from the FULL registered roster.
  --
  -- This is the "one-to-one feel" option, and it is the direct descendant of
  -- Sanqui's `game_pokemon`, which picked 150 of 721 and dropped them into the
  -- cartridge's dex slots.  He had to: the ROM had ~253 slots.  We do not, so
  -- the pick restricts APPEARANCE only -- every species stays registered and
  -- every save stays scrub-safe.
  function Encounters.subset(species, seed, size)
    size = size or 151
    local pool = {}
    for _, record in ipairs(species) do pool[#pool + 1] = record.id end
    table.sort(pool) -- stable input order regardless of registry iteration
    -- Fisher-Yates driven by a seeded LCG, so the same seed always yields the
    -- same roster on every machine.
    local state = (hash32(tostring(seed or "")) % 2147483647) + 1
    local function nextInt(n)
      -- modulo rather than a bitmask: see the note on hash32 above
      state = (1103515245 * state + 12345) % 2147483648
      return (state % n) + 1
    end
    for i = #pool, 2, -1 do
      local j = nextInt(i)
      pool[i], pool[j] = pool[j], pool[i]
    end
    local chosen = {}
    for i = 1, math.min(size, #pool) do chosen[pool[i]] = true end
    return chosen
  end

  -- Even thresholds out of 256.  Encounter.lua accepts "its own `buckets` of
  -- any length, as long as the last entry is 256 and there are as many slots
  -- as buckets" -- which is what makes per-map slot expansion possible without
  -- touching constants.encounterBuckets at all.
  --
  -- That matters for compatibility: the global constant is a `deep` registry
  -- key, where a bare list CONCATENATES rather than replaces (patching a
  -- 20-entry list onto vanilla's 10 yields 30 and a broken rate table). The
  -- per-map field sidesteps that entirely and cannot collide with any mod that
  -- is not already editing the same map.
  local function evenBuckets(n)
    local out = {}
    for i = 1, n do out[i] = math.floor(i * 256 / n + 0.5) end
    out[n] = 256
    return out
  end

  -- Place `rows` onto a map, additively.
  --
  -- `extended` widens the slot table so added species have somewhere to go
  -- instead of evicting vanilla ones; without it we append nothing, because
  -- appending past the bucket count would create unreachable slots.
  function Encounters.place(mod, mapId, kind, rows, opts)
    if #rows == 0 then return 0 end
    local payload = { slots = { __append = rows } }
    if opts.extended then
      -- vanilla base (10) plus what we add; the runtime reconciliation in
      -- main.lua corrects this if another mod changes the count later.
      payload.buckets = evenBuckets(opts.baseSlots + #rows)
    end
    local ok, err = pcall(function()
      mod.content.encounters:patch(mapId, { [kind] = payload })
    end)
    if not ok then
      mod.log:warn("encounters %s.%s: %s", mapId, kind, tostring(err))
      return 0
    end
    return #rows
  end

  function Encounters.apply(mod, Data, opts)
    local allowed = nil
    if opts.available == "subset151" then
      allowed = Encounters.subset(Data.SPECIES, opts.subsetSeed, 151)
      mod.log:info("RANDOM 151: restricting wild appearances to a seeded "
        .. "subset (seed %q); all species remain registered",
        tostring(opts.subsetSeed))
    end

    -- Maps another mod is known to author wholesale.  With YIELD TO OTHER MODS
    -- on we leave these alone entirely rather than appending into a table
    -- someone else curated -- their placement is deliberate and ours is
    -- heuristic, so theirs should win.
    local contested = {}
    if opts.respectOtherMods then
      for _, id in ipairs(Data.CONTESTED_MAPS or {}) do contested[id] = true end
    end

    local placed, yielded = 0, 0
    for mapId, kinds in pairs(Data.PLACEMENT or {}) do
      if contested[mapId] then
        yielded = yielded + 1
      else
        for kind, rows in pairs(kinds) do
          local filtered = {}
          for _, row in ipairs(rows) do
            if not allowed or allowed[row.species] then
              filtered[#filtered + 1] = { level = row.level,
                                          species = row.species }
            end
          end
          placed = placed + Encounters.place(mod, mapId, kind, filtered, {
            extended = opts.extended,
            baseSlots = 10, -- vanilla Gen 1 table width
          })
        end
      end
    end

    mod.log:info("placed %d wild slots (%d maps yielded to other mods)",
      placed, yielded)
    if not opts.extended and placed > 0 then
      mod.log:warn("VANILLA SLOTS: appended slots beyond the 10 vanilla "
        .. "buckets are unreachable until buckets are widened")
    end
    return placed
  end

  return Encounters
end

-- ================= entry chunk =================
-- Dex Expansion -- registers species beyond the original 151 for Gen1Recomp.
--
-- The one architectural rule this mod is built around:
--
--     EXISTENCE IS UNCONDITIONAL.  AVAILABILITY IS OPTIONAL.
--
-- Every species in data/species.lua is registered on every boot, regardless
-- of settings.  Nothing is ever withheld from the `pokemon` registry.
--
-- That is not a style preference, it is a save-safety requirement.  The
-- engine's save scrubber (src/core/SaveData.lua) deletes dex flags for
-- species the dataset does not know:
--
--     for id in pairs(dex[key]) do
--       if not known(data.pokemon, id) then dex[key][id] = nil end
--     end
--
-- ...and blanks Hall of Fame entries the same way.  Because mod options are
-- GLOBAL preferences rather than per-save state, a settings-driven roster
-- would mean flipping one option silently destroys dex progress in every
-- existing save.  So the "151 subset" option restricts where species APPEAR
-- (encounters, and trainer parties once that lands), never whether they
-- EXIST.
--
-- Verified against gen1recomp:
--   * constants.dexSize is DERIVED from the highest `dex` in the merged
--     registry (src/core/Data.lua seedDefaults), so registering 649 species
--     widens the Pokedex UI with no constant to set.
--   * species are string-keyed and saves are Lua source, so there is no
--     255-index ceiling anywhere in the gameplay path.

local mod = ...

local Data = __dexpand_require("data.species")
local GrowthRates = __dexpand_require("src.growth_rates")
local Encounters = __dexpand_require("src.encounters")
local Moves = __dexpand_require("src.moves")

-- ---------------------------------------------------------------- options

mod.options:define({
  { key = "encounterMode", label = "WILD PLACEMENT", type = "choice",
    default = "extended",
    choices = {
      { "EXTENDED SLOTS", "extended" },
      { "VANILLA SLOTS", "vanilla" },
      { "DATA ONLY", "dataonly" },
    } },
  { key = "available", label = "SPECIES IN WILD", type = "choice",
    default = "all",
    choices = { { "ALL", "all" }, { "RANDOM 151", "subset151" } } },
  { key = "subsetSeed", label = "SUBSET SEED", type = "text",
    default = "", maxLen = 24 },
  { key = "respectOtherMods", label = "YIELD TO OTHER MODS",
    type = "toggle", default = true },
  -- MODERN registers the new types and every Gen 2-5 level-up move.
  -- RETRO registers them too -- existence is unconditional, so a saved mon
  -- can never know a move that stops existing -- but resolves learnsets
  -- through data/retro.lua and retypes species onto the original 15.
  { key = "moveMode", label = "MOVES & TYPES", type = "choice",
    default = "modern",
    choices = { { "MODERN", "modern" }, { "RETRO GEN 1", "retro" } } },
})

local encounterMode = mod.options:get("encounterMode") or "extended"
local available = mod.options:get("available") or "all"
local subsetSeed = mod.options:get("subsetSeed") or ""
local respect = mod.options:get("respectOtherMods")
if respect == nil then respect = true end

-- ----------------------------------------------------------- growth rates
-- Gen 1 ships five curves; Gen 2+ species also use ERRATIC and FLUCTUATING.
-- The `growth_rates` registry takes an expForLevel function
-- (src/mods/Schemas.lua R.growth_rates), validated to be increasing.

for id, fn in pairs(GrowthRates.CURVES) do
  local ok, err = pcall(function()
    mod.content.growth_rates:register(id, { expForLevel = fn })
  end)
  if not ok then
    mod.log:warn("growth rate %s not registered: %s", id, tostring(err))
  end
end

-- ------------------------------------------------------- types and moves
-- Runs BEFORE species registration: `types` and `level1Moves` are
-- f.id() cross-references, so the targets must be registered first or the
-- post-merge check fails the whole mod.

local moveMode = mod.options:get("moveMode") or "modern"
local resolveMove, resolveTypes = Moves.apply(mod, moveMode)

-- --------------------------------------------------------------- species
-- Field names below are the extractor's own, taken from
-- gen1recomp/tools/extract/pokemon.py rather than from the schema's
-- idealized shape, so these records sit alongside the vanilla ones exactly.
--
-- The randomizer's eligibility gate (species_manifest.lua) additionally
-- requires: id matching the registry key, positive integer dex, all five
-- base stats as integers 1..255, >=1 type, non-empty growthRate, DENSE
-- level1Moves / learnset / evolutions arrays, and non-empty spriteFront AND
-- spriteBack.  A record missing either sprite is silently excluded from the
-- randomizer's pool, which is why sprite paths are mandatory here.

local registered, skipped = 0, 0

local function validate(record)
  if type(record.id) ~= "string" or record.id == "" then return "id" end
  if type(record.dex) ~= "number" or record.dex < 1 then return "dex" end
  local s = record.baseStats
  if type(s) ~= "table" then return "baseStats" end
  for _, key in ipairs({ "hp", "attack", "defense", "speed", "special" }) do
    local v = s[key]
    if type(v) ~= "number" or v < 1 or v > 255 or v ~= math.floor(v) then
      return "baseStats." .. key
    end
  end
  if type(record.types) ~= "table" or #record.types < 1 then return "types" end
  if type(record.growthRate) ~= "string" or record.growthRate == "" then
    return "growthRate"
  end
  -- dense arrays: the gate rejects sparse ones outright
  for _, key in ipairs({ "level1Moves", "learnset", "evolutions" }) do
    if type(record[key]) ~= "table" then return key end
  end
  if type(record.spriteFront) ~= "string" or record.spriteFront == "" then
    return "spriteFront"
  end
  if type(record.spriteBack) ~= "string" or record.spriteBack == "" then
    return "spriteBack"
  end
  return nil
end

for _, record in ipairs(Data.SPECIES) do
  record = Moves.rewrite(record, resolveMove, resolveTypes)
  local bad = validate(record)
  if bad then
    skipped = skipped + 1
    mod.log:warn("species %s skipped: invalid %s",
      tostring(record.id), bad)
  else
    local ok, err = pcall(function()
      mod.content.pokemon:register(record.id, record)
    end)
    if ok then
      registered = registered + 1
    else
      skipped = skipped + 1
      mod.log:warn("species %s failed to register: %s",
        record.id, tostring(err))
    end
  end
end

mod.log:info("registered %d species (%d skipped)", registered, skipped)

-- ------------------------------------------------- randomizer metadata
-- exports.registerSpeciesMeta(id, { legendary = bool, stage = "basic" |
-- "middle" | "final" }) freezes at mods.loaded, so this has to run in the
-- entry chunk.  Without it the randomizer derives stages itself and
-- legendary status falls back silently -- which is why the manifest
-- declares pokemon_randomizer as an OPTIONAL dependency: that is what makes
-- the load order deterministic rather than incidental.

local function handOffMetadata()
  local randomizer = mod.find and mod.find("pokemon_randomizer")
  if not randomizer then return end
  local exports = randomizer.exports
  if not (exports and exports.registerSpeciesMeta) then
    mod.log:warn("pokemon_randomizer present but exposes no "
      .. "registerSpeciesMeta; stages will be derived")
    return
  end
  local sent = 0
  for _, record in ipairs(Data.SPECIES) do
    local meta = {}
    local ext = record.dexExpansion or {}
    if ext.legendary ~= nil then meta.legendary = ext.legendary end
    if ext.stage ~= nil then meta.stage = ext.stage end
    -- the API asserts at least one field is present
    if meta.legendary ~= nil or meta.stage ~= nil then
      local ok = pcall(exports.registerSpeciesMeta, record.id, meta)
      if ok then sent = sent + 1 end
    end
  end
  mod.log:info("handed %d species metadata rows to the randomizer", sent)
end

handOffMetadata()

-- ------------------------------------------------------------ encounters

if encounterMode == "dataonly" then
  mod.log:info("DATA ONLY: no encounter tables written; wild placement is "
    .. "left to the randomizer or another mod")
else
  Encounters.apply(mod, Data, {
    extended = encounterMode == "extended",
    available = available,
    subsetSeed = subsetSeed,
    respectOtherMods = respect,
  })
end

-- ------------------------------------- runtime bucket reconciliation
-- The safety net, and the reason this mod does not simply trust its own
-- arithmetic.
--
-- src/world/Encounter.lua rolls a slot as:
--     for i, threshold in ipairs(grass.buckets or buckets) do
--       if pick < threshold then local slot = grass.slots[i] ...
--
-- so bucket count and slot count MUST agree.  Registries are not readable
-- during the entry chunk (merge has not happened yet), and other mods
-- append or replace slots on the same maps, so the final count is not
-- knowable at registration time.  Two failure modes follow:
--
--   more slots than buckets -> the tail slots are unreachable (harmless)
--   more buckets than slots -> `slot` is nil and the roll yields NO
--                              encounter, silently cutting the encounter
--                              rate
--
-- The second one is a real bug, and it happens whenever a mod that loads
-- after this one replaces a slot list wholesale.  So rather than trusting
-- the merge, rebuild the thresholds from the slot count that actually
-- survived, evenly spaced to 256.

local function evenBuckets(n)
  local out = {}
  for i = 1, n do out[i] = math.floor(i * 256 / n + 0.5) end
  out[n] = 256 -- Encounter.lua requires the last entry to be exactly 256
  return out
end

mod.events:on("game.ready", function(game)
  local encounters = game and game.data and game.data.encounters
  if type(encounters) ~= "table" then return end
  local fixed = 0
  for mapId, def in pairs(encounters) do
    if type(def) == "table" then
      for _, kind in ipairs({ "grass", "water" }) do
        local table_ = def[kind]
        if type(table_) == "table" and type(table_.slots) == "table" then
          local slots = #table_.slots
          local current = table_.buckets and #table_.buckets or nil
          if slots > 0 and current ~= slots then
            table_.buckets = evenBuckets(slots)
            fixed = fixed + 1
            mod.log:debug("%s.%s: rebuilt %d buckets for %d slots",
              tostring(mapId), kind, current or 0, slots)
          end
        end
      end
    end
  end
  if fixed > 0 then
    mod.log:info("reconciled encounter buckets on %d tables", fixed)
  end
end)
